// src/App.jsx
import React, { useState } from 'react';
import StudentList from './components/StudentList';
import StudentForm from './components/StudentForm';
import StudentDetails from './components/StudentDetails';
import * as studentService from './services/studentService';
import './styles.css';

export default function App(){
  const [students, setStudents] = useState([]);
  const [mode, setMode] = useState('list'); // 'list' | 'form' | 'details'
  const [formMode, setFormMode] = useState('add'); // 'add' | 'edit'
  const [selected, setSelected] = useState(null);

  const loadStudents = () => {
    studentService.getStudents().then(data => setStudents(data)).catch(err => {
      alert('Failed to load students');
      console.error(err);
    });
  };

  const handleAdd = () => { setFormMode('add'); setSelected(null); setMode('form'); };
  const handleEdit = (s) => { setFormMode('edit'); setSelected(s); setMode('form'); };
  const handleView = (s) => { setSelected(s); setMode('details'); };
  const handleDelete = (s) => {
    if (!window.confirm(`Delete ${s.name}?`)) return;
    studentService.deleteStudent(s.id).then(() => {
      alert('Deleted. Click Load Students to refresh.');
    }).catch(err => { alert('Delete failed'); console.error(err); });
  };

  const handleFormSubmit = (payload) => {
    if (formMode === 'add') {
      studentService.addStudent(payload).then(() => {
        alert('Student added. Click Load Students to refresh.');
        setMode('list');
      }).catch(err => { alert('Add failed'); console.error(err); });
    } else {
      studentService.updateStudent(payload.id, payload).then(() => {
        alert('Student updated. Click Load Students to refresh.');
        setMode('list');
      }).catch(err => { alert('Update failed'); console.error(err); });
    }
  };

  return (
    <div className="app">
      <div className="header">
        <div>
          <div className="title">Student Result System</div>
          <div className="subtitle">Add • View • Edit • Delete — manual load (use Load Students)</div>
        </div>

        <div style={{display:'flex',gap:8}}>
          <button className="btn ghost" onClick={loadStudents}>Load Students</button>
          <button className="btn" onClick={() => { setMode('list'); setSelected(null); }}>Clear Selection</button>
        </div>
      </div>

      <div className="container">
        <div>
          {mode === 'list' && (
            <StudentList
              students={students}
              onLoad={loadStudents}
              onAdd={handleAdd}
              onEdit={handleEdit}
              onDelete={handleDelete}
              onView={handleView}
            />
          )}

          {mode === 'form' && (
            <StudentForm
              mode={formMode}
              initial={selected}
              onCancel={() => setMode('list')}
              onSubmit={handleFormSubmit}
            />
          )}
        </div>

        <div>
          <StudentDetails student={selected} />
        </div>
      </div>
    </div>
  );
}
